class FitnessTracker:
    # Symbolic constants to replace magic numbers
    BMR_MULTIPLIER_SEDENTARY = 1.2
    BMR_MULTIPLIER_ACTIVE = 1.6
    BMR_MULTIPLIER_MODERATE = 1.4

    BMR_WEIGHT_FACTOR = 10
    BMR_HEIGHT_FACTOR = 6.25
    BMR_AGE_FACTOR = -5
    BMR_MALE_BASE = 5
    BMR_FEMALE_BASE = -161

    # Condition return values
    CONDITION_OBESE = 1
    CONDITION_UNDERWEIGHT = -1
    CONDITION_NORMAL = 0

    def __init__(self, height, weight, age, sex) -> None:
        self._height = height
        self._weight = weight
        self.age = age
        self.sex = sex
        self._BMI_std = {
            "male": [20, 25],
            "female": [19, 24]
        }

    @property
    def height(self):
        return self._height

    @height.setter
    def height(self, value):
        self._height = value

    @property
    def weight(self):
        return self._weight

    @weight.setter
    def weight(self, value):
        self._weight = value

    def get_BMI(self):
        return self.weight / self.height ** 2

    def get_BMI_range(self):
        # Replace Temp with Query: inline the logic to get the range directly
        if self.sex == "male":
            return self._BMI_std["male"]
        else:
            return self._BMI_std["female"]

    def condition_judge(self):
        BMI = self.get_BMI()
        BMI_range = self.get_BMI_range()

        # Decompose Conditional & Introduce Explaining Variable
        if BMI > BMI_range[1]:
            return self.CONDITION_OBESE
        elif BMI < BMI_range[0]:
            return self.CONDITION_UNDERWEIGHT
        else:
            return self.CONDITION_NORMAL

    def calculate_BMR(self):
        # Extract Method
        if self.sex == "male":
            return (
                self.BMR_WEIGHT_FACTOR * self.weight
                + self.BMR_HEIGHT_FACTOR * self.height
                + self.BMR_AGE_FACTOR * self.age
                + self.BMR_MALE_BASE
            )
        else:
            return (
                self.BMR_WEIGHT_FACTOR * self.weight
                + self.BMR_HEIGHT_FACTOR * self.height
                + self.BMR_AGE_FACTOR * self.age
                + self.BMR_FEMALE_BASE
            )

    def get_activity_multiplier(self):
        # Extract Method & Replace Nested Conditional with Guard Clauses (logical simplification)
        condition = self.condition_judge()
        if condition == self.CONDITION_OBESE:
            return self.BMR_MULTIPLIER_SEDENTARY
        elif condition == self.CONDITION_UNDERWEIGHT:
            return self.BMR_MULTIPLIER_ACTIVE
        else:
            return self.BMR_MULTIPLIER_MODERATE

    def calculate_calorie_intake(self):
        # Replace Temp with Query / Inline Temp
        BMR = self.calculate_BMR()
        multiplier = self.get_activity_multiplier()
        return BMR * multiplier
